import { chromium } from 'playwright';import fs from 'fs';import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',key=process.env.KEY,label=process.env.LABEL,route=process.env.ROUTE,OUT='sep18-sg-root-cards-'+key;fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const req=[];p.on('request',r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())});
const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);let resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(13500);
const row=await p.evaluate(({label,route,req,themeId})=>{const root=document.querySelector('[data-sqsg]'),view=root?.querySelector('[data-sqsg-view]');const cards=[...document.querySelectorAll('[data-sqsg-view] a.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').replace(/\s+/g,' ').trim(),meta:(a.querySelector('small')?.textContent||'').replace(/\s+/g,' ').trim(),href:a.getAttribute('href')||'',itemCount:a.dataset.sqItemCount||'',countSource:a.dataset.sqCountSource||'',equipmentLock:a.dataset.sqEquipmentRootLock||'',equipmentSanitized:a.dataset.sqEquipmentRootSanitized||'',authority:a.dataset.sqAuthorityCard||''}));return{label,route,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},cards,cardCount:cards.length,viewData:view?[...view.attributes].filter(x=>x.name.startsWith('data-')).reduce((o,x)=>(o[x.name]=x.value,o),{}):{},fetches:req.filter(u=>u.includes('/collections/')&&u.includes('/products.json')),fetchCount:req.filter(u=>u.includes('/collections/')&&u.includes('/products.json')).length,h1:(document.querySelector('h1')?.textContent||'').replace(/\s+/g,' ').trim(),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,req,themeId:THEME});row.httpStatus=resp?.status()??null;fs.writeFileSync(path.join(OUT,'result.json'),JSON.stringify(row,null,2));await p.screenshot({path:path.join(OUT,'screenshots','root.png'),fullPage:false});console.log('SGROOTCARDS',JSON.stringify(row));await c.close();await b.close();